ame="amount" min="1" max="<?=e((string)$stats['available'])?>" required></label><label>Method<select name="method"><option>Bank Transfer</option><option>JazzCash</option><option>EasyPaisa</option></select></label><label>Account title<input name="account_title" required></label><label>Account / wallet number<input name="account_reference" required></label><button class="mp550-btn wide">Request payout</button></form><h3>Recent payout requests</h3><?php foreach($payouts as $p):?><div class="mini-row"><span><?=mp550_money((float)$p['amount'])?></span><em class="status <?=e($p['status'])?>"><?=e($p['status'])?></em></div><?php endforeach;?></aside></section>
